    // Compute global thread id
    // ------------------------------------------------------------------
    mov.u32 %tid, %tid.x;          // threadIdx.x
    mov.u32 %bid, %ctaid.x;        // blockIdx.x
    mov.u32 %gridDim, %nctaid.x;   // gridDim.x

    mul.lo.u32 %tid, %bid, %ctaid.x;   // blockIdx * blockDim
    add.u32 %tid, %tid, %tid;          // add threadIdx.x -> global thread id (reuse %tid)
    cvt.u64.u32 %global_tid, %tid;

