    // Decompose linear index into (b, c, o)
    // ------------------------------------------------------------------
    .reg .u32 %bc, %rem, %b, %c, %o;
    mul.lo.u32 %bc, %C, %O;               // C * O
    div.u32 %b, %tid, %bc;                // b = idx / (C*O)
    mul.lo.u32 %rem, %b, %bc;
    sub.u32 %rem, %tid, %rem;             // rem = idx - b*(C*O)

