    mul.lo.u32 %addr, %addr, %L;
    add.u32 %addr, %addr, %c;
    mul.lo.u32 %addr, %addr, %L;
    add.s32 %addr, %addr, %pos;
    cvt.u64.u32 %addr, %addr;
    mul.u64 %addr, %addr, 2;              // fp16 size
