    add.u32 %out_addr, %out_addr, %o;
    cvt.u64.u32 %out_addr, %out_addr;
    mul.u64 %out_addr, %out_addr, 2;      // fp16 size
    add.u64 %out_addr, %out_addr, %out_ptr;

