# Python wrapper that loads and launches the PTX kernel
# --------------------------------------------------------------
import torch
from ptx_harness import ptx_load, ptx_launch  # assumed provided by the harness

class ModelNew:
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0,
                 dilation: int = 1, return_indices: bool = False):
        # store parameters
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.dilation = dilation
        self.return_indices = return_indices  # not supported, kept for API compatibility

        # load PTX module
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, inputs):
        # inputs[0] is the tensor x (fp16)
        x = inputs[0]
        assert x.dtype == torch.float16, "Input must be fp16"

        B, C, L = x.shape
        K = self.kernel_size
        S = self.stride
        P = self.padding
        D = self.dilation

        # compute output length (same formula as PyTorch)
        effective_k = D * (K - 1) + 1
        O = (L + 2 * P - effective_k) // S + 1

        # allocate output tensor
        out = torch.empty((B, C, O), dtype=torch.float16, device=x.device)

        # launch configuration
        threads_per_block = 256
        total_threads = B * C * O
        blocks = (total_threads + threads_per_block - 1) // threads_per_block

        # kernel arguments (all passed as 64‑bit values where needed)
        args = [
            x.data_ptr(),          # input_ptr
            out.data_ptr(),        # output_ptr
            B,                     # batch
            C,                     # channels
            L,                     # in_len
            O,                     # out_len
            K,                     # kernel_size
            S,                     # stride
            P,                     # padding
            D                      # dilation
        ]

        # launch the kernel
        ptx_launch(self.module, "maxpool1d_fp16",
                    grid=(blocks, 1, 1),
                    block=(threads_per_block, 1, 1),
                    args=args)

        return out
